source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]

    invariants = (
        (lambda r, c: r),
        (lambda r, c: c),
        (lambda r, c: c - r),
        (lambda r, c: r + c),
    )
    choices = []
    for key_fn in invariants:
        lines = {}
        for r, c, color in cells:
            lines.setdefault(key_fn(r, c), set()).add(color)
        if all(len(colors) == 1 for colors in lines.values()):
            choices.append((len(lines), lines, key_fn))
    if not choices:
        return [row[:] for row in grid]

    _, lines, key_fn = min(choices, key=lambda item: item[0])
    line_colors = {key: next(iter(colors)) for key, colors in lines.items()}
    period = next(
        n for n in range(1, 2 * max(h, w) + 2)
        if len({key % n for key in line_colors}) == len(line_colors)
        or all(len({color for key, color in line_colors.items() if key % n == residue}) == 1
               for residue in {key % n for key in line_colors})
    )
    residue_colors = {}
    for key, color in line_colors.items():
        residue_colors[key % period] = color

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            key = key_fn(r, c)
            row.append(residue_colors.get(key % period, 0))
        out.append(row)
    return out
'''
